class Filtering(Cog):
    async def _has_watch_regex_match(self, text: str) -> Tuple[Union[bool, re.Match], Optional[str]]:
        """
        Return True if `text` matches any regex from `word_watchlist` or `token_watchlist` configs.
        `word_watchlist`'s patterns are placed between word boundaries while `token_watchlist` is
        matched as-is. Spoilers are expanded, if any, and URLs are ignored.
        Second return value is a reason written to database about blacklist entry (can be None).
        """
        if SPOILER_RE.search(text):
            text = self._expand_spoilers(text)
        text = self.clean_input(text)
        if URL_RE.search(text):
            return False, None
        watchlist_patterns = self._get_filterlist_items('filter_token', allowed=False)
        for pattern in watchlist_patterns:
            match = re.search(pattern, text, flags=re.IGNORECASE)
            if match:
                return match, self._get_filterlist_value('filter_token', pattern, allowed=False)['comment']
        return False, None
class PyPi(Cog):
    @command(name="pypi", aliases=("package", "pack"))
    async def get_package_info(self, ctx: Context, package: str) -> None:
        """Provide information about a specific package from PyPI."""
        embed = Embed(title=random.choice(NEGATIVE_REPLIES), colour=Colours.soft_red)
        embed.set_thumbnail(url=PYPI_ICON)
        error = True
        if characters := re.search(ILLEGAL_CHARACTERS, package):
            embed.description = f"Illegal character(s) passed into command: '{escape_markdown(characters.group(0))}'"
        else:
            async with self.bot.http_session.get(URL.format(package=package)) as response:
                if response.status == 404:
                    embed.description = "Package could not be found."
                elif response.status == 200 and response.content_type == "application/json":
                    response_json = await response.json()
                    info = response_json["info"]
                    embed.title = f"{info['name']} v{info['version']}"
                    embed.url = info["package_url"]
                    embed.colour = next(PYPI_COLOURS)
                    summary = escape_markdown(info["summary"])
                    if summary and not summary.isspace():
                        embed.description = summary
                    else:
                        embed.description = "No summary provided."
                    error = False
                else:
                    embed.description = "There was an error when fetching your PyPi package."
                    log.trace(f"Error when fetching PyPi package: {response.status}.")
        if error:
            error_message = await ctx.send(embed=embed)
            await wait_for_deletion(error_message, (ctx.author.id,), timeout=INVALID_INPUT_DELETE_DELAY)
            if not (ctx.message.mentions or ctx.message.role_mentions):
                with suppress(NotFound):
                    await ctx.message.delete()
                    await error_message.delete()
        else:
            await ctx.send(embed=embed)

class JupyterApp(Application):
    config_dir = Unicode()
    @property
    def config_file_paths(self):
        path = jupyter_config_path()
        if self.config_dir not in path:
            path.insert(0, self.config_dir)
        path.insert(0, os.getcwd())
        return path
    def migrate_config(self):
        """Migrate config/data from IPython 3"""
        if os.path.exists(os.path.join(self.config_dir, "migrated")):
            return
        from .migrate import get_ipython_dir, migrate
        if not os.path.exists(get_ipython_dir()):
            return
        migrate()
    def _find_subcommand(self, name):
        name = f"{self.name}-{name}"
        return which(name)
    @catch_config_error
    def initialize(self, argv=None):
        if argv is None:
            argv = sys.argv[1:]
        if argv:
            subc = self._find_subcommand(argv[0])
            if subc:
                self.argv = argv
                self.subcommand = subc
                return
        self.parse_command_line(argv)
        cl_config = deepcopy(self.config)
        if self._dispatching:
            return
        self.migrate_config()
        self.load_config_file()
        self.update_config(cl_config)
        if allow_insecure_writes:
            issue_insecure_write_warning()
    def start(self):
        """Start the whole thing"""
        if self.subcommand:
            os.execv(self.subcommand, [self.subcommand] + self.argv[1:])
            raise NoStart()
        if self.subapp:
            self.subapp.start()
            raise NoStart()
        if self.generate_config:
            self.write_default_config()
            raise NoStart()
def jupyter_config_path():
    """Return the search path for Jupyter config files as a list.
    If the JUPYTER_PREFER_ENV_PATH environment variable is set, the
    environment-level directories will have priority over user-level
    directories.
    If the Python site.ENABLE_USER_SITE variable is True, we also add the
    appropriate Python user site subdirectory to the user-level directories.
    """
    if os.environ.get("JUPYTER_NO_CONFIG"):
        return [jupyter_config_dir()]
    paths: list = []
    if os.environ.get("JUPYTER_CONFIG_PATH"):
        paths.extend(p.rstrip(os.sep) for p in os.environ["JUPYTER_CONFIG_PATH"].split(os.pathsep))
    user = [jupyter_config_dir()]
    if site.ENABLE_USER_SITE:
        userbase: Optional[str]
        if hasattr(site, "getuserbase"):
            userbase = site.getuserbase()
        else:
            userbase = site.USER_BASE
        if userbase:
            userdir = os.path.join(userbase, "etc", "jupyter")
            if userdir not in user:
                user.append(userdir)
    env = [p for p in ENV_CONFIG_PATH if p not in SYSTEM_CONFIG_PATH]
    if envset("JUPYTER_PREFER_ENV_PATH"):
        paths.extend(env)
        paths.extend(user)
    else:
        paths.extend(user)
        paths.extend(env)
    paths.extend(SYSTEM_CONFIG_PATH)
    return paths
allow_insecure_writes = os.getenv("JUPYTER_ALLOW_INSECURE_WRITES", "false").lower() in ("true", "1")

