    def __call__(self, base, econtext, call, path_items):
        request = econtext.get('request')
        base = self.traverse(base, request, path_items)
        if call is False:
            return base
        if getattr(base, '__call__', _marker) is not _marker or \
           isinstance(base, type):
            return base()
        return base

