class RawDataStorage(object):
    def __init__(self, obj=None, filename=None, gzip=True):
                self.save_raw_data(obj, filename, gzip)
            self.load_raw_data(filename, gzip)
    def save_raw_data(self, obj, filename, gzip):
        """
        Saves data to HDF5 file.
        Parameters
        ----------
        obj : pyblock.BeamBlockMultiVolume
            BeamBlockMultiVolume object to save to file
        filename : str
            Path and name of file to save data too. If this file exists it will
            be removed first.
        gzip : bool
            True - Save file will be gzipped, removing previous gzipped file if
                   it exists.
            False - Save file will not be compressed.
        """
        if filename is None:
            filename = './temporary_block_data.h5'
        os.system('rm ' + filename)
        h = h5py.File(filename)
        v = getattr(obj, 'Azimuth')
        h.create_dataset('Azimuth', data=np.array(v), dtype=np.array(v).dtype)
        for var in ['rain_refl', 'drizz_zdr']:
            for k, v in getattr(obj, var).items():
                h.create_dataset(var + '_' + k, data=np.array(v), dtype=float)
        for var in ['DZ', 'DR', 'KD']:
            for k, v in obj.fsc_data[var].items():
                h.create_dataset('fsc_data_' + var.lower() + k,
                                 data=np.array(v), dtype=float)
        h.close()
        if gzip:
            os.system('rm ' + filename + '.gz')
            os.system('gzip ' + filename)
    def load_raw_data(self, filename, gzip):
        """
        Loads data from HDF5 file.
        Parameters
        ----------
        filename : str
            Full path and name of file that hosts BeamBlockMultiVolume data.
        gzip : bool
            True - File to be loaded is gzipped.
            False - File to be loaded is not gzipped
        """
        if filename is None:
            filename = './temporary_block_data.h5'
        if gzip:
            os.system('gzip -d ' + filename + '.gz')
        h = h5py.File(filename, 'r')
        self.Azimuth = np.array(h['Azimuth'])
        for var in ['rain_refl', 'drizz_zdr']:
            v = {}
            cnt = 0
            for key in h.keys():
                if str(key)[:9] == var:
                    cnt += 1
            for i in range(cnt):
                v[str(i)] = np.array(h[var + '_' + str(i)])
            setattr(self, var, v)
        self.fsc_data = {}
        for var in ['DZ', 'KD', 'DR']:
            cnt = 0
            self.fsc_data[var] = {}
            for key in h.keys():
                if str(key)[:11] == 'fsc_data_' + var.lower():
                    cnt += 1
            for i in range(cnt):
                self.fsc_data[var][str(i)] = np.array(
                    h['fsc_data_' + var.lower() + str(i)])
        h.close()
        if gzip:
            os.system('gzip  ' + filename)

class BaseUser(Table, tablename="piccolo_user"):
    _max_password_length = 128
    @classmethod
    def _validate_password(cls, password: str):
        """
        Validate the raw password. Used by :meth:`update_password` and
        :meth:`create_user`.
        :param password:
            The raw password e.g. ``'hello123'``.
        :raises ValueError:
            If the password fails any of the criteria.
        """
        if not password:
            raise ValueError("A password must be provided.")
        if len(password) < cls._min_password_length:
            raise ValueError("The password is too short.")
        if len(password) > cls._max_password_length:
            raise ValueError("The password is too long.")
        if password.startswith("pbkdf2_sha256"):
            logger.warning(
                "Tried to create a user with an already hashed password."
            )
            raise ValueError("Do not pass a hashed password.")
    @classmethod
    async def update_password(cls, user: t.Union[str, int], password: str):
        """
        The password is the raw password string e.g. ``'password123'``.
        The user can be a user ID, or a username.
        """
        if isinstance(user, str):
            clause = cls.username == user
        elif isinstance(user, int):
            clause = cls.id == user
        else:
            raise ValueError(
                "The `user` arg must be a user id, or a username."
            )
        cls._validate_password(password=password)
        password = cls.hash_password(password)
        await cls.update({cls.password: password}).where(clause).run()
    @classmethod
    async def login(cls, username: str, password: str) -> t.Optional[int]:
        """
        Make sure the user exists and the password is valid. If so, the
        ``last_login`` value is updated in the database.
        :returns:
            The id of the user if a match is found, otherwise ``None``.
        """
        if len(username) > cls.username.length:
            logger.warning("Excessively long username provided.")
            return None
        if len(password) > cls._max_password_length:
            logger.warning("Excessively long password provided.")
            return None
        response = (
            await cls.select(cls._meta.primary_key, cls.password)
            .where(cls.username == username)
            .first()
            .run()
        )
        if not response:
            return None
        stored_password = response["password"]
        algorithm, iterations_, salt, hashed = cls.split_stored_password(
            stored_password
        )
        iterations = int(iterations_)
        if cls.hash_password(password, salt, iterations) == stored_password:
            if iterations != cls._pbkdf2_iteration_count:
                await cls.update_password(username, password)
            await cls.update({cls.last_login: datetime.datetime.now()}).where(
                cls.username == username
            )
            return response["id"]
        else:
            return None

